head.script:
///////// 1. 변수 및 선언 영역 /////////
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.listUsrSync();
        $c.bns.BnsPanelToGroupBox(panel_2);
        $c.bns.BnsPanelToGroupBox(pnl_IsurSearch);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS22100.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_HandOverIsuList_OnLoadCompleted
 * @description dts_HandOverIsuList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_HandOverIsuList_OnLoadCompleted = function(rowcount) {
    try {
        cnt1.setValue(rowcount + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS22100.dts_HandOverIsuList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_TakeOverIsuList_OnLoadCompleted
 * @description dts_TakeOverIsuList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_TakeOverIsuList_OnLoadCompleted = function(rowcount) {
    try {
        cnt2.setValue(rowcount + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS22100.dts_TakeOverIsuList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_HandOverIsuList_OnLoadError
 * @description dts_HandOverIsuList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_HandOverIsuList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_HandOverIsuList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22100.dts_HandOverIsuList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_TakeOverIsuList_OnLoadError
 * @description dts_TakeOverIsuList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_TakeOverIsuList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_TakeOverIsuList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22100.dts_TakeOverIsuList_OnLoadError" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
        scwin.listUsrSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22100.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
        scwin.listUsrSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22100.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name btn_Select_HandOver_onclick
 * @description btn_Select_HandOver 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Select_HandOver_onclick = async function() {
    try {
        await scwin.selectTakeOver();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22100.btn_Select_HandOver_onclick" });
    }
};

/**
 * @method
 * @name btn_All_HandOver_onclick
 * @description btn_All_HandOver 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_All_HandOver_onclick = async function() {
    try {
        await scwin.allHandOver();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22100.btn_All_HandOver_onclick" });
    }
};

/**
 * @method
 * @name txb_IsurCd_onkeypress
 * @description txb_IsurCd onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurCd_onkeypress = function() {
    try {
        if (event.keyCode === 13) scwin.listUsrSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS22100.txb_IsurCd_onkeypress" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.listUsrSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS22100.btn_Search_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name allHandOver
 * @description ---------------------------------------------------------------------------- 예외처리 -------------------------------------------------------------------------------
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.allHandOver = async function() {
    // gubun = 1;
    let rowcnt = dts_HandOverIsuList.getRowCount();
    if (rowcnt === 0) {
        await $c.win.alert("처리할 사항이 없습니다.");
        return;
    }
    if (!scwin.cntDatasetRowCheck(dts_HandOverIsuList)) {
        await $c.win.alert("적용할 체크사항이 없습니다.");
    } else {
        let msg = $c.stf.getMessageParam("MSG-A006", "예외처리");
        let res = window.confirm(msg);
        if (res) {

            // dts_Save.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
            dts_Save.setBroadcast(false);
            for (let i = 1; i <= dts_HandOverIsuList.getRowCount(); i++) {
                if (dts_HandOverIsuList.getCellData(i, "CHK_FLAG") === 1) {
                    dts_Save.insertRow();
                    dts_Save.setCellData(dts_Save.getRowPosition(), "ISUR_CD", dts_HandOverIsuList.getCellData(i, "ISUR_CD"));
                }
            }
            dts_Save.setBroadcast(true, true);
            trs_Save.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_Save",
                action : "/bns/IsuChgEtc.do",
                ref : "dts_Save",
                target : "trs_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

/**
 * @method
 * @name selectTakeOver
 * @description ---------------------------------------------------------------------------- 신청제한처리 -------------------------------------------------------------------------------
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectTakeOver = async function() {
    // gubun = 1;
    let rowcnt = dts_TakeOverIsuList.getRowCount();
    if (rowcnt === 0) {
        await $c.win.alert("처리할 사항이 없습니다.");
        return;
    }
    if (!scwin.cntDatasetRowCheck(dts_TakeOverIsuList)) {
        await $c.win.alert("적용할 체크사항이 없습니다.");
    } else {
        let msg = $c.stf.getMessageParam("MSG-A006", "신청제한");
        let res = window.confirm(msg);
        if (res) {

            // dts_Save.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
            dts_Save.setBroadcast(false);
            for (let i = 1; i <= dts_TakeOverIsuList.getRowCount(); i++) {
                if (dts_TakeOverIsuList.getCellData(i, "CHK_FLAG") === 1) {
                    dts_Save.insertRow();
                    dts_Save.setCellData(dts_Save.getRowPosition(), "ISUR_CD", dts_TakeOverIsuList.getCellData(i, "ISUR_CD"));
                }
            }
            dts_Save.setBroadcast(true, true);
            trs_Save.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_Save",
                action : "/bns/IsuChgEtc.do",
                ref : "dts_Save",
                target : "trs_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
// filter된 법인목록

/**
 * @method
 * @name listUsrSync
 * @description 조회
 * @returns {void}
 * @hidden N
 */
scwin.listUsrSync = function() {
    vIsurNm = txb_IsurCd.getValue();
    let dsNm = 'BNS_ISUR_INFO';
    let qryId = 'lds.stf.bnslistbzappl.select.listIsurCd.bnsApplPosblTmExcptYn';
    let param = '&{P}V_ISUR_NM=' + vIsurNm;
    param += '&{P}V_EXCPT_YN=N';
    $c.bns.fn_SearchBns('ULDBNS22100.xml', dts_HandOverIsuList, dsNm, qryId, param);
    let dsNm = 'BNS_ISUR_INFO';
    let qryId = 'lds.stf.bnslistbzappl.select.listIsurCd.bnsApplPosblTmExcptYn';
    let param = '&{P}V_ISUR_NM=';
    param += '&{P}V_EXCPT_YN=Y';
    $c.bns.fn_SearchBns('ULDBNS22100.xml', dts_TakeOverIsuList, dsNm, qryId, param);
};

/**
 * @method
 * @name cntDatasetRowCheck
 * @description ---------------------------------------------------------------------------- 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. -------------------------------------------------------------------------------
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.cntDatasetRowCheck = function(sval) {
    cCnt = 0;
    for (i = 1; i <= sval.getRowCount(); i++) {
        // alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name grd_HandOverIsuList_CanColumnPosChange
 * @description grd Hand Over Isu List Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_HandOverIsuList_CanColumnPosChange = function(row, colid) {
    return true;
};

/**
 * @method
 * @name grd_TakeOverIsuList_CanColumnPosChange
 * @description grd Take Over Isu List Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_TakeOverIsuList_CanColumnPosChange = function(row, colid) {
    return true;
};
